def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Simple approach: find first differing character and length difference
    min_len = min(len(s_in), len(s_out))

    # Check for character differences
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found a difference at position i
            old_char = s_in[i]
            new_char = s_out[i]
            return (old_char, new_char, i)

    # If we get here, one string is prefix of the other
    if len(s_in) > len(s_out):
        # Removal case
        removed = s_in[len(s_out):]
        return (removed, "", len(s_out))
    elif len(s_out) > len(s_in):
        # Addition case  
        added = s_out[len(s_in):]
        return ("", added, len(s_in))

    return ("", "", -1)  # No change

# Test our approach
inputs = ['wuk', 'wudx', 'ik', 'guxef', 'zdgkwg']
outputs = ['wuzbw', 'wudzb', 'vzb', 'guzbef', 'zdgzbwwg']

